const watts = items[0].json.data.result[0].value[1];
const durationHours = 0.5; // Example: 30 min task
const kwh = (watts * durationHours) / 1000;
const localCost = kwh * 0.10;
const cloudCost = 1.50; // Example GPT-4o cost for same task

return {
  watts: parseFloat(watts).toFixed(2),
  local_cost_usd: localCost.toFixed(4),
  cloud_savings_usd: (cloudCost - localCost).toFixed(2),
  is_local_cheaper: localCost < cloudCost
};
